                          return (...args: unknown[]) => {
                            const operation = Reflect.apply(
                              Reflect.get(selected, "where"),
                              selected,
                              args,
                            ) as PromiseLike<unknown>;
                            return Promise.resolve(operation).then((result) => {
                              expiredAtPublication = true;
                              f.clock.advance(120001);
                              return result;
                            });
                          };
